#include <algorithm>
#include <cmath>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <random>

struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};
struct Put {
    double operator()(double S, double K) const { return std::max(K - S, 0.0); }
};
struct Digital {
    double operator()(double S, double K) const { return S > K ? 1.0 : 0.0; }
};

struct XorShift64 {  // a tiny engine: any type with these four members works
    using result_type = std::uint64_t;
    static constexpr result_type min() { return 0; }
    static constexpr result_type max() { return UINT64_MAX; }
    result_type operator()() {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        return state;
    }
    std::uint64_t state;
};

struct Market {
    double S0, K, r, sigma, T;
};

template <typename Payoff, typename Rng>
double mc_price(const Payoff& payoff, Rng& rng, const Market& m, long paths) {
    std::normal_distribution<double> z(0.0, 1.0);
    const double drift = (m.r - 0.5 * m.sigma * m.sigma) * m.T;
    const double vol = m.sigma * std::sqrt(m.T);
    double sum = 0.0;
    for (long i = 0; i < paths; ++i) {
        const double ST = m.S0 * std::exp(drift + vol * z(rng));  // one exact GBM step
        sum += payoff(ST, m.K);
    }
    return std::exp(-m.r * m.T) * sum / paths;  // discounted mean payoff
}

int main() {
    const Market m{100.0, 100.0, 0.05, 0.2, 1.0};
    const long paths = 100000;
    std::mt19937_64 mt(42);
    XorShift64 xs{42};
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "call    " << mc_price(Call{}, mt, m, paths) << '\n';
    std::cout << "put     " << mc_price(Put{}, mt, m, paths) << '\n';
    std::cout << "digital " << mc_price(Digital{}, mt, m, paths) << '\n';
    std::cout << "call, xorshift " << mc_price(Call{}, xs, m, paths) << '\n';
    return 0;
}

