#include <algorithm>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <random>

struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};

struct Market {
    double S0, K, r, sigma, T;
};

double norm_cdf(double x) { return 0.5 * std::erfc(-x / std::sqrt(2.0)); }

double bs_call(const Market& m) {  // the closed form from the options lesson
    const double d1 = (std::log(m.S0 / m.K) + (m.r + 0.5 * m.sigma * m.sigma) * m.T) / (m.sigma * std::sqrt(m.T));
    const double d2 = d1 - m.sigma * std::sqrt(m.T);
    return m.S0 * norm_cdf(d1) - m.K * std::exp(-m.r * m.T) * norm_cdf(d2);
}

struct Stats {  // Welford's running mean and variance, from the stats lesson
    long n = 0;
    double mean = 0.0, m2 = 0.0;
    void add(double x) {
        ++n;
        const double d = x - mean;
        mean += d / n;
        m2 += d * (x - mean);
    }
    double se() const { return std::sqrt(m2 / (n - 1) / n); }  // standard error of the mean
};

template <typename Payoff, typename Rng>
Stats simulate(const Payoff& payoff, Rng& rng, const Market& m, long n, bool antithetic) {
    std::normal_distribution<double> z(0.0, 1.0);
    const double drift = (m.r - 0.5 * m.sigma * m.sigma) * m.T;
    const double vol = m.sigma * std::sqrt(m.T);
    const double disc = std::exp(-m.r * m.T);
    Stats s;
    for (long i = 0; i < n; ++i) {
        const double e = z(rng);
        double x = payoff(m.S0 * std::exp(drift + vol * e), m.K);
        if (antithetic) {  // the mirror path -e, averaged in as one sample
            x = 0.5 * (x + payoff(m.S0 * std::exp(drift - vol * e), m.K));
        }
        s.add(disc * x);
    }
    return s;
}

void report(long n, const char* what, const Stats& s, double exact) {
    std::cout << std::setw(6) << n << ' ' << what << ": " << std::setprecision(4) << s.mean << " +- " << s.se()
              << " (off by " << std::setprecision(2) << (s.mean - exact) / s.se() << " se)\n";
}

int main() {
    const Market m{100.0, 100.0, 0.05, 0.2, 1.0};
    const double exact = bs_call(m);
    std::cout << std::fixed << std::setprecision(4) << "black-scholes " << exact << '\n';
    for (long n : {1000L, 10000L, 100000L}) {
        std::mt19937_64 rng(42);
        report(n, "paths", simulate(Call{}, rng, m, n, false), exact);
    }
    std::mt19937_64 rng(42);
    report(50000, "pairs", simulate(Call{}, rng, m, 50000, true), exact);
    return 0;
}

