// -O2
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <random>
#include <thread>
#include <vector>

struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};
struct Market {
    double S0, K, r, sigma, T;
};

struct Stats {  // Welford, plus a merge for two chunks' stats
    long n = 0;
    double mean = 0.0, m2 = 0.0;
    void add(double x) {
        ++n;
        const double d = x - mean;
        mean += d / n;
        m2 += d * (x - mean);
    }
    void merge(const Stats& o) {
        const long total = n + o.n;
        const double d = o.mean - mean;
        mean += d * o.n / total;
        m2 += o.m2 + d * d * n * o.n / total;
        n = total;
    }
    double se() const { return std::sqrt(m2 / (n - 1) / n); }
};

template <typename Payoff>
Stats run_chunk(const Payoff& payoff, const Market& m, long paths, std::uint64_t seed, unsigned chunk) {
    std::seed_seq seq{seed, std::uint64_t{chunk}};
    std::mt19937_64 rng(seq);  // this chunk's own engine
    std::normal_distribution<double> z(0.0, 1.0);
    const double drift = (m.r - 0.5 * m.sigma * m.sigma) * m.T, vol = m.sigma * std::sqrt(m.T);
    const double disc = std::exp(-m.r * m.T);
    Stats s;
    for (long i = 0; i < paths; ++i) {
        s.add(disc * payoff(m.S0 * std::exp(drift + vol * z(rng)), m.K));
    }
    return s;
}

template <typename Payoff>
Stats mc_threads(const Payoff& payoff, const Market& m, long paths, unsigned chunks, std::uint64_t seed) {
    std::vector<Stats> parts(chunks);
    std::vector<std::thread> threads;
    for (unsigned c = 0; c < chunks; ++c) {
        const long count = paths / chunks + (c < paths % chunks ? 1 : 0);  // a fixed split
        threads.emplace_back([&, c, count] { parts[c] = run_chunk(payoff, m, count, seed, c); });
    }
    for (std::thread& t : threads) {
        t.join();
    }
    Stats total;
    for (const Stats& s : parts) {  // chunk 0, 1, 2, ... in every run
        total.merge(s);
    }
    return total;
}

int main() {
    const Market m{100.0, 100.0, 0.05, 0.2, 1.0};
    const Stats a = mc_threads(Call{}, m, 4000000, 4, 42);
    const Stats b = mc_threads(Call{}, m, 4000000, 4, 42);
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "4 chunks: " << a.mean << " +- " << a.se() << '\n';
    std::cout << "run again: " << (a.mean == b.mean && a.m2 == b.m2 ? "identical" : "different") << '\n';
    std::cout << "1 chunk:  " << mc_threads(Call{}, m, 4000000, 1, 42).mean << '\n';
    return 0;
}

